*---------------------------------------------------------------
* Generated by cobc370 from bigws.cbl
* Standard OS/360 entry linkage. SYS1.COBLIB is never referenced.
* DISPLAY and report output are served by our own COBRT runtime.
*---------------------------------------------------------------
BIGWS    CSECT
         STM   14,12,12(13)        save caller's registers
         BALR  12,0                first code base
COBBEG   EQU   *
         USING COBBEG,12
         LA    11,2048(,12)        second code base
         LA    11,2048(,11)
         USING COBBEG+4096,11
         LA    10,2048(,11)        third code base
         LA    10,2048(,10)
         USING COBBEG+8192,10
         ST    13,SAVEAREA+4       backward chain to caller
         LA    0,SAVEAREA
         ST    0,8(13)             forward chain from caller
         LR    13,0                our save area is now current
         SPIE  COBSPIE,((1,15))    report program checks by line
* MAIN-PARA.
P0000    DS    0H
T0000    DS    0H
* MOVE MSG1 -> MSG2
         L     8,BL0000            base locator
         USING WSC0000,8
         L     9,BL0001            base locator
         USING WSC0001,9
         MVC   D0003(5),D0000      alphanumeric move
T0001    DS    0H
* DISPLAY
         MVC   DSPBUF+0(5),D0003
         LA    1,PARM0001
         L     15,VDISP
         BALR  14,15
T0002    DS    0H
* ADD 100 -> ACC
         L     2,D0004
         CVD   2,DWK               binary -> packed
         ZAP   PWK1(16),DWK(8)
         ZAP   PWK2(16),K0001(16)  literal
         AP    PWK1(16),PWK2(16)
         ZAP   DWK(8),PWK1(16)
         CVB   2,DWK               packed -> binary
         ST    2,D0004
T0003    DS    0H
* MOVE ACC -> OUT-NUM
         L     2,D0004
         CVD   2,DWK               binary -> packed
         ZAP   PWK1(16),DWK(8)
         UNPK  D0005(5),PWK1(16)   packed -> zoned
         OI    D0005+4,X'F0'       unsigned: force an F zone
T0004    DS    0H
* DISPLAY
         MVC   DSPBUF+0(5),D0005
         LA    1,PARM0002
         L     15,VDISP
         BALR  14,15
T0005    DS    0H
* STOP RUN
         L     15,VTERM            close anything the runtime opened
         BALR  14,15
         L     13,4(13)            restore caller's save area
         LM    14,12,12(13)        restore caller's registers
         SR    15,15               return code 0
         BR    14                  return to caller
VDISP    DC    V(COBDISP)
VTERM    DC    V(COBTERM)
PARM0001 DC    A(DSPBUF)
         DC    X'80',AL3(LEN0001)  last parameter
LEN0001  DC    H'5'
PARM0002 DC    A(DSPBUF)
         DC    X'80',AL3(LEN0002)  last parameter
LEN0002  DC    H'5'
* work areas for decimal arithmetic
DWK      DS    D                   CVD/CVB doubleword
PWK1     DS    PL16
PWK2     DS    PL16
EDSRC    DS    PL16                ED source, sized to the selectors
EDWK     DS    CL64                ED pattern and result
ZWK      DS    CL24                zoned work area
MULT8    DS    PL8                 MP right operand
DIVR8    DS    PL8                 DP divisor
QTMP     DS    PL8                 DP quotient
WK0      DS    PL16                expression stack
WK1      DS    PL16
WK2      DS    PL16
WK3      DS    PL16
WK4      DS    PL16
WK5      DS    PL16
K0001    DC    PL16'100'           numeric constants
* base locator cells, one per 4096 bytes of COBWS
BL0000   DC    A(WSC0000)
BL0001   DC    A(WSC0001)
DSPBUF   DS    CL121               DISPLAY line
SAVEAREA DS    18F
* program-check exit: report the source line, then let it abend
COBSPIE  DS    0H
         USING COBSPIE,15
         STM   14,12,SPIEREGS      R15 is our base on entry
         LR    9,15                keep a base across the WTO
         DROP  15
         USING COBSPIE,9
         LR    10,1                the PIE
*  the interruption code, as the digit people know it
         SR    7,7
         IC    7,7(,10)            low byte of the interruption code
         N     7,SPIE15
         LA    7,SPIEHEX(7)
         MVC   SPIECODE(1),0(7)
*  the interrupt address, as an offset into this module
         L     2,8(,10)            second word of the old PSW
         N     2,SPIEADR           leaves the instruction address
         S     2,SPIEBEG           relative to the entry point
*  the last table entry at or before it names the statement
         L     3,SPIETAB
         LH    4,SPIENUM
         SR    5,5                 no line yet
SPIELOOP LTR   4,4
         BZ    SPIEFND
         LH    6,0(,3)             this statement's offset
         CR    6,2
         BH    SPIEFND             past it: the previous one is the ans
         LH    5,2(,3)
         LA    3,4(,3)
         BCTR  4,0
         B     SPIELOOP
SPIEFND  CVD   5,SPIEDW
         UNPK  SPIELINE(5),SPIEDW+5(3)
         OI    SPIELINE+4,X'F0'
         WTO   MF=(E,SPIEWTO)      into the job log, beside the abend
*  cancel the exit and back up to the failing instruction,
*  so the abend happens for real -- same code, same dump
         SR    2,2
         IC    2,7(,10)            the interruption code
         A     2,SPIE3000
         ABEND (2),DUMP
SPIEHEX  DC    C'0123456789ABCDEF'
SPIE15   DC    F'15'
SPIE3000 DC    F'3000'
SPIEADR  DC    X'00FFFFFF'
SPIEBEG  DC    A(COBBEG)
SPIETAB  DC    A(SPIELTB)
SPIENUM  DC    H'6'                statements in the table
SPIEREGS DS    15F
SPIEDW   DS    D
SPIEWTO  WTO   'COBC370: PROGRAM CHECK 0C0 AT SOURCE LINE 00000',      X
               MF=L
SPIECODE EQU   SPIEWTO+29,1        the 0C? digit, patched above
SPIELINE EQU   SPIEWTO+46,5        the line number, likewise
* statement offsets, ascending, paired with source lines
SPIELTB  DS    0H
         DC    AL2(T0000-COBBEG),AL2(13)
         DC    AL2(T0001-COBBEG),AL2(14)
         DC    AL2(T0002-COBBEG),AL2(15)
         DC    AL2(T0003-COBBEG),AL2(16)
         DC    AL2(T0004-COBBEG),AL2(17)
         DC    AL2(T0005-COBBEG),AL2(18)
COBWS    CSECT
WSC0000  EQU   COBWS               chunk origins
WSC0001  EQU   COBWS+4096
* WORKING-STORAGE
D0000    DC    CL5'ALPHA'          MSG1 PIC X(5)
         DS    XL3                 reserve the rest of a table
D0001    DC    2100C' '            PAD1 PIC X(2100)
         DS    XL4                 reserve the rest of a table
D0002    DC    2100C' '            PAD2 PIC X(2100)
         DS    XL4                 reserve the rest of a table
D0003    DC    CL5' '              MSG2 PIC X(5)
         DS    XL3                 reserve the rest of a table
D0004    DC    FL4'42'             ACC PIC S9(5)v0 COMP
         DS    XL4                 reserve the rest of a table
D0005    DC    CL5'00000'          OUT-NUM PIC 9(5)v0 DISP
*---------------------------------------------------------------
* COBRT -- our runtime. Nothing here is from SYS1.COBLIB.
* DISPLAY reaches SYSOUT through QSAM directly, which is the
* same access-method path IKFCBL00 uses for its own file I/O.
* Not reentrant: MVS 3.8j batch does not require it.
*---------------------------------------------------------------
COBRT    CSECT
         ENTRY COBDISP,COBTERM,COBWRL,COBDATE,COBACC,COBUPSI
*
* COBDISP -- write one line to SYSOUT.
*   R1 -> A(text), A(halfword length).  Opens SYSOUT on demand.
*
COBDISP  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE1+4
         LA    11,RTSAVE1
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(text)
         L     3,4(0,1)            A(length)
         LH    4,0(0,3)            length
         CLI   RTOPEN,X'01'        already open?
         BE    COBD010
         OPEN  (RTDCB,OUTPUT)
         MVI   RTOPEN,X'01'
COBD010  MVI   RTLINE,C' '         ASA: single space
         MVC   RTLINE+1(120),RTLINE  blank the text area
         LTR   4,4
         BNP   COBD020             empty: emit a blank line
         CH    4,RTMAX
         BNH   COBD015
         LH    4,RTMAX             truncate at line width
COBD015  BCTR  4,0                 EX wants length-1
         EX    4,COBDMVC
COBD020  PUT   RTDCB,RTLINE
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
COBDMVC  MVC   RTLINE+1(0),0(2)    executed, never fallen into
*
* COBUPSI -- set the eight switches from the EXEC PARM.
*
* PARM='/UPSI(10100000)' is the form IBM's later compilers
* take, and the one the runtime looks for: the literal UPSI
* anywhere in the parameter text, then the next eight 0 or 1
* characters, leftmost being UPSI-0. Anything else leaves all
* eight off, which is the documented default.
COBUPSI  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE6+4
         LA    11,RTSAVE6
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(parameter text)
         LA    2,0(0,2)            drop the end-of-list bit
         XC    RTUPSI,RTUPSI       all off unless the PARM says otherwi
         LH    3,0(0,2)            its length
         LA    4,2(0,2)            the text itself
         CH    3,UPSIMIN           room for UPSI and eight digits?
         BL    UPSX
         SH    3,UPSIMIN
         LA    3,1(3)              positions worth trying
UPS10    CLC   0(4,4),UPSITAG
         BE    UPS15
         LA    4,1(4)
         BCT   3,UPS10
         B     UPSX                no UPSI in the parameter
UPS15    LA    4,4(4)              past the tag
         CLI   0(4),C'0'
         BE    UPS20
         CLI   0(4),C'1'
         BE    UPS20
         LA    4,1(4)              skip a ( or an =
UPS20    SR    5,5                 the byte being built
         LA    6,8                 eight of them
UPS30    SLL   5,1
         CLI   0(4),C'1'
         BNE   UPS40
         LA    5,1(5)
UPS40    LA    4,1(4)
         BCT   6,UPS30
         ST    5,RTUPSI            the byte, for the caller to store
UPSX     L     13,4(13)
         L     15,RTUPSI           the byte, while R12 is still ours
         ST    15,16(13)           into the save area's R15 slot
         LM    14,12,12(13)
         BR    14
*
* COBACC -- one transfer from SYSIN into the caller's item.
*
* General rule 2 on II-53 leaves the size of a transfer to the
* implementor: here it is one 80-column record. The buffer is
* blanked first, so a receiver wider than a card is padded and
* a read past the last card returns spaces rather than the
* card before it.
*
* Parameter list: A(item), A(halfword length).
COBACC   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE5+4
         LA    11,RTSAVE5
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(item)
         L     3,4(0,1)            A(length)
         LH    4,0(0,3)            length
         MVI   ACCBUF,C' '
         MVC   ACCBUF+1(255),ACCBUF  blank the buffer
         CLI   ACCEOFF,X'01'       already at end of file?
         BE    COBA020
         CLI   ACCOPEN,X'01'       already open?
         BE    COBA010
         OPEN  (ACCDCB,INPUT)
         MVI   ACCOPEN,X'01'
COBA010  LA    1,COBA030
         STCM  1,7,ACCDCB+33       into DCBEODAD
         GET   ACCDCB,ACCBUF       one card
         B     COBA020
COBA030  MVI   ACCEOFF,X'01'       end of file: the buffer stays blank
COBA020  LTR   4,4
         BNP   COBA040             nothing to store
         CH    4,ACCMAX
         BNH   COBA035
         LH    4,ACCMAX            one MVC is 256 bytes
COBA035  BCTR  4,0                 EX wants length-1
         EX    4,COBAMVC
COBA040  L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
COBAMVC  MVC   0(0,2),ACCBUF       patched by EX
*
* COBTERM -- close SYSOUT if COBDISP ever opened it.
*
COBTERM  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE2+4
         LA    11,RTSAVE2
         ST    11,8(13)
         LR    13,11
         CLI   ACCOPEN,X'01'
         BNE   COBT005
         CLOSE (ACCDCB)
         MVI   ACCOPEN,X'00'
COBT005  CLI   RTOPEN,X'01'
         BNE   COBT010
         CLOSE (RTDCB)
         MVI   RTOPEN,X'00'
COBT010  L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
*
* COBDATE -- fill an 8-byte field with MM/DD/YY.
*   R1 -> the field.  TIME DEC hands back the date as packed
*   00YYDDDF, which is Julian, so the day of year has to be
*   walked into a month and a day.
*
COBDATE  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE4+4
         LA    11,RTSAVE4
         ST    11,8(13)
         LR    13,11
         LR    2,1                 the field, before TIME takes R1
         TIME  DEC                 R0 = HHMMSSth, R1 = 00YYDDDF
         ST    1,DTPACK
         UNPK  DTZONE(7),DTPACK(4)  '00YYDDD'
         OI    DTZONE+6,X'F0'
         PACK  DTDW(8),DTZONE+4(3)
         CVB   3,DTDW              day of the year
         PACK  DTDW(8),DTZONE+2(2)
         CVB   4,DTDW              the year
         N     4,DTF3              zero if a leap year -- 1901-2099, so
*                             mod 4 is the whole rule
         LA    5,1                 month
         LA    6,DTMON
DT010    SR    7,7
         IC    7,0(0,6)            days in this month
         CH    5,DTH2              February?
         BNE   DT020
         LTR   4,4
         BNZ   DT020
         LA    7,1(0,7)            29 this year
DT020    CR    3,7
         BNH   DT030               the day falls in this month
         SR    3,7
         LA    5,1(0,5)
         LA    6,1(0,6)
         B     DT010
DT030    CVD   5,DTDW
         UNPK  0(2,2),DTDW+6(2)    MM
         OI    1(2),X'F0'
         MVI   2(2),C'/'
         CVD   3,DTDW
         UNPK  3(2,2),DTDW+6(2)    DD
         OI    4(2),X'F0'
         MVI   5(2),C'/'
         MVC   6(2,2),DTZONE+2     YY, already zoned
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
DTMON    DC    AL1(31,28,31,30,31,30,31,31,30,31,30,31)
DTF3     DC    F'3'
DTH2     DC    H'2'
DTPACK   DS    F
DTZONE   DS    CL8
DTDW     DS    D
RTSAVE4  DS    18F
*
* COBWRL -- advance the paper and write one report line.
*   R1 -> A(dcb), A(current line), A(target line), A(buffer)
*
COBWRL   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE3+4
         LA    11,RTSAVE3
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(dcb)
         L     3,4(0,1)            A(current line)
         L     4,8(0,1)            A(target line)
         L     5,12(0,1)           A(buffer)
         LH    6,0(0,3)
         LH    7,0(0,4)
COBW010  LA    8,1(0,6)
         CR    8,7                 already at the line before the targe
         BNL   COBW020
         PUT   (2),RTBLNK          skip a line
         LA    6,1(0,6)
         B     COBW010
COBW020  PUT   (2),(5)
         STH   7,0(0,3)            current line = target
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
RTBLNK   DC    CL133' '            a blank line, ASA single space
RTSAVE3  DS    18F
RTOPEN   DC    X'00'
RTMAX    DC    H'120'
RTLINE   DC    CL121' '            ASA byte + 120 columns
RTSAVE1  DS    18F
RTSAVE2  DS    18F
RTSAVE5  DS    18F
RTSAVE6  DS    18F
RTUPSI   DS    F
UPSITAG  DC    C'UPSI'
UPSIMIN  DC    H'12'               UPSI, a bracket, eight digits
ACCOPEN  DC    X'00'
ACCEOFF  DC    X'00'
ACCBUF   DC    CL256' '            one card from SYSIN, blank padded
ACCMAX   DC    H'256'
ACCDCB   DCB   DDNAME=SYSIN,DSORG=PS,MACRF=(GM),                       X
               EODAD=0
RTDCB    DCB   DDNAME=SYSOUT,DSORG=PS,MACRF=(PM),RECFM=FBA,            X
               LRECL=121,BLKSIZE=121
         END
